CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522085508_InitialCreate') THEN
    CREATE TABLE "Apartments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "BlockName" text NOT NULL,
        "UnitNumber" text NOT NULL,
        "IsOccupied" boolean NOT NULL,
        "ResidentName" text NOT NULL,
        CONSTRAINT "PK_Apartments" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522085508_InitialCreate') THEN
    CREATE TABLE "Tickets" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" text NOT NULL,
        "Description" text NOT NULL,
        "Status" text NOT NULL,
        "Priority" text NOT NULL,
        "AssignedTo" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Tickets" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522085508_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260522085508_InitialCreate', '10.0.8');
    END IF;
END $EF$;
COMMIT;

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522151149_NormalizedSchema') THEN
    ALTER TABLE "Apartments" DROP COLUMN "ResidentName";
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522151149_NormalizedSchema') THEN
    ALTER TABLE "Apartments" ADD "BuilderId" integer NOT NULL DEFAULT 0;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522151149_NormalizedSchema') THEN
    CREATE TABLE "Builders" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompanyName" text NOT NULL,
        "ContactEmail" text NOT NULL,
        CONSTRAINT "PK_Builders" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522151149_NormalizedSchema') THEN
    CREATE TABLE "Managers" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FirstName" text NOT NULL,
        "LastName" text NOT NULL,
        "KeycloakUserId" text NOT NULL,
        CONSTRAINT "PK_Managers" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522151149_NormalizedSchema') THEN
    CREATE TABLE "Residents" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FirstName" text NOT NULL,
        "LastName" text NOT NULL,
        "KeycloakUserId" text NOT NULL,
        "ApartmentId" integer NOT NULL,
        CONSTRAINT "PK_Residents" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Residents_Apartments_ApartmentId" FOREIGN KEY ("ApartmentId") REFERENCES "Apartments" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
