        CONSTRAINT "PK_ApartmentManagers" PRIMARY KEY ("ApartmentsId", "ManagersId"),
        CONSTRAINT "FK_ApartmentManagers_Apartments_ApartmentsId" FOREIGN KEY ("ApartmentsId") REFERENCES "Apartments" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ApartmentManagers_Managers_ManagersId" FOREIGN KEY ("ManagersId") REFERENCES "Managers" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

