DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522151931_SeedBulkData') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Apartments"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Apartments") + 1,
            nextval(pg_get_serial_sequence('"Apartments"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Builders"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Builders") + 1,
            nextval(pg_get_serial_sequence('"Builders"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Managers"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Managers") + 1,
            nextval(pg_get_serial_sequence('"Managers"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Residents"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Residents") + 1,
            nextval(pg_get_serial_sequence('"Residents"', 'Id'))),
        false);
    END IF;
END $EF$;

